package com.bank.bonus;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SecondHighestDemo {
    private static final Logger log = Logger.getLogger("Bonus");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("1000000")),  // highest
            new Employee("Priya", new BigDecimal("800000")),    // 2nd (tie)
            new Employee("Amit", new BigDecimal("800000")),     // 2nd (tie)
            new Employee("Neha", new BigDecimal("600000")));
        BonusService service = new BonusService();

        List<String> second = service.secondHighestEarners(staff);
        log.info(() -> "Second-highest earners (incl. ties): " + second);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
    Employee(String name, BigDecimal salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/BonusService.java ───
class BonusService {
    List<String> secondHighestEarners(List<Employee> staff) {
        Optional<BigDecimal> secondSalary = staff.stream()
            .map(Employee::getSalary)
            .distinct()                                   // distinct salary values
            .sorted(Comparator.reverseOrder())             // descending
            .skip(1)                                       // drop the highest
            .findFirst();                                  // → 2nd-highest salary

        return secondSalary.map(sal -> staff.stream()
                .filter(e -> e.getSalary().compareTo(sal) == 0)  // ALL tied at that salary
                .map(Employee::getName)
                .toList())
            .orElse(List.of());
    }
}
